export interface RateCircuitBreakerOptions {
  /** Number of failures in the sliding window required to open the circuit. */
  failureThreshold: number;
  /** Length of the sliding failure window, in milliseconds. */
  failureWindowMs: number;
  /** Time the circuit remains open before a single probe is admitted. */
  cooldownMs: number;
  /** Injectable monotonic-enough clock. */
  now?: () => number;
}

export interface RateCircuitBreakerSnapshot {
  state: RateCircuitBreakerState;
  failureCount: number;
  probeInFlight: boolean;
}

interface FailureWindowOptions {
  failureThreshold: number;
  failureWindowMs: number;
  cooldownMs: number;
  now?: () => number;
}

function positiveFinite(value: number, name: string): number {
  if (!Number.isFinite(value) || value <= 0) {
    throw new RangeError(`${name} must be a positive finite number`);
  }
  return value;
}

function normalizeOptions(options: FailureWindowOptions): Required<RateCircuitBreakerOptions> {
  if (options === null || typeof options !== "object") {
    throw new TypeError("rate circuit breaker options are required");
  }
  const failureThreshold = positiveFinite(options.failureThreshold, "failureThreshold");
  if (!Number.isInteger(failureThreshold)) {
    throw new RangeError("failureThreshold must be a positive integer");
  }
  return {
    failureThreshold,
    failureWindowMs: positiveFinite(options.failureWindowMs, "failureWindowMs"),
    cooldownMs: positiveFinite(options.cooldownMs, "cooldownMs"),
    now: options.now ?? Date.now,
  };
}

/**
 * A deterministic, opt-in circuit breaker for unusually high failure rates.
 *
 * The breaker does not execute work itself: callers must consult allow() before
 * performing an effect and report the outcome with recordSuccess() or
 * recordFailure(). An open circuit rejects calls until cooldown expires.
 */
export class RateCircuitBreaker {
  private readonly options: Required<RateCircuitBreakerOptions>;
  private readonly failures: number[] = [];
  private circuitState: RateCircuitBreakerState = "closed";
  private openedAt = 0;
  private probeInFlight = false;

  constructor(options: RateCircuitBreakerOptions) {
    this.options = normalizeOptions(options);
  }

  get state(): RateCircuitBreakerState {
    this.refreshState();
    return this.circuitState;
  }

  /**
   * Returns whether one call may proceed. In half-open state this admits only
   * one probe until that probe's outcome is reported.
   */
  allow(at?: number): boolean {
    const now = this.clockTime(at);
    this.refreshState(now);

    if (this.circuitState === "open") {
      return false;
    }

    if (this.circuitState === "half-open") {
      if (this.probeInFlight) {
        return false;
      }
      this.probeInFlight = true;
      return true;
    }

    return true;
  }

  /** Alias for callers that prefer an explicit request-shaped name. */
  allowRequest(at?: number): boolean {
    return this.allow(at);
  }

  /** Reports a successful call. A successful half-open probe closes the circuit. */
  recordSuccess(at?: number): void {
    const now = this.clockTime(at);
    this.refreshState(now);

    if (this.circuitState === "half-open") {
      this.close();
      return;
    }

    this.probeInFlight = false;
  }

  /** Reports a failed call and opens the circuit when the threshold is reached. */
  recordFailure(at?: number): void {
    const now = this.clockTime(at);
    this.refreshState(now);

    if (this.circuitState === "half-open") {
      this.open(now);
      return;
    }

    this.probeInFlight = false;
    this.failures.push(now);
    this.pruneFailures(now);
    if (this.failures.length >= this.options.failureThreshold) {
      this.open(now);
    }
  }

  onSuccess(at?: number): void {
    this.recordSuccess(at);
  }

  onFailure(at?: number): void {
    this.recordFailure(at);
  }

  /** Runs an admitted operation and reports its outcome to the breaker. */
  async execute<T>(operation: () => T | Promise<T>, at?: number): Promise<T> {
    if (!this.allow(at)) {
      throw new RateCircuitOpenError();
    }
    try {
      const result = await operation();
      this.recordSuccess(at);
      return result;
    } catch (error) {
      this.recordFailure(at);
      throw error;
    }
  }

  snapshot(): RateCircuitBreakerSnapshot {
    this.refreshState();
    return {
      state: this.circuitState,
      failureCount: this.failures.length,
      probeInFlight: this.probeInFlight,
    };
  }

  reset(at?: number): void {
    const now = this.clockTime(at);
    this.close();
    void now;
  }

  private clockTime(at?: number): number {
    const value = at ?? this.options.now();
    if (!Number.isFinite(value)) {
      throw new TypeError("circuit breaker clock must return a finite number");
    }
    return value;
  }

  private refreshState(now = this.clockTime()): void {
    if (
      this.circuitState === "open" &&
      now - this.openedAt >= this.options.cooldownMs
    ) {
      this.circuitState = "half-open";
      this.probeInFlight = false;
    }
    if (this.circuitState === "closed") {
      this.pruneFailures(now);
    }
  }

  private pruneFailures(now: number): void {
    const cutoff = now - this.options.failureWindowMs;
    while (this.failures.length > 0 && this.failures[0] < cutoff) {
      this.failures.shift();
    }
  }

  private open(now: number): void {
    this.circuitState = "open";
    this.openedAt = now;
    this.probeInFlight = false;
    this.failures.length = 0;
  }

  private close(): void {
    this.circuitState = "closed";
    this.openedAt = 0;
    this.probeInFlight = false;
    this.failures.length = 0;
  }
}

export class RateCircuitOpenError extends Error {
  constructor(message = "rate circuit breaker is open") {
    super(message);
    this.name = "RateCircuitOpenError";
  }
}

export function createRateCircuitBreaker(
  options: RateCircuitBreakerOptions,
): RateCircuitBreaker {
  return new RateCircuitBreaker(options);
}

export const createRateCircuitBreakerForTests = createRateCircuitBreaker;
